    this.activeTransaction = transaction;
    var cancellation = new Promise(function (resolve) { cancelResolve = resolve; });
    var adapterAttempt;
    try { adapterAttempt = Promise.resolve(invoke()); }
    catch (error) { adapterAttempt = Promise.reject(error); }
