      var alpha = style.alpha === undefined ? Math.max(0, pulse.life / PP.data.config.sonar.waveSeconds) : style.alpha;
      var segments = 120;
      var sourceKind = pulse.source === 'chorus' ? 'chorus' : 'signal';
      var pulseObstacles = sourceKind === 'chorus'
