        if (!drawImage('effect-impact-fracture', player.x, player.y, 210, 210, stage.elapsed * 8, impactAlpha)) drawRing(player.x, player.y, 82 + (1 - impactAlpha) * 70, '#ff786f', 12, impactAlpha);
